import React, { useState } from "react";
import "./Filters.css";

export default function Filters({ onCategoryChange, onPriceChange, onSortChange }) {
  const [category, setCategory] = useState("all");
  const [price, setPrice] = useState("all");
  const [sort, setSort] = useState("new");

  const handleCategory = (value) => {
    setCategory(value);
    if (onCategoryChange) onCategoryChange(value);
  };

  const handlePrice = (value) => {
    setPrice(value);
    if (onPriceChange) onPriceChange(value);
  };

  const handleSort = (value) => {
    setSort(value);
    if (onSortChange) onSortChange(value);
  };

  return (
    <div className="filters-wrapper">
      <h3 className="filters-title">Filtres</h3>

      {/* CATEGORY */}
      <div className="filter-section">
        <h4 className="filter-label">Catégorie</h4>

        {[
          { id: "all", label: "Tous" },
          { id: "abaya", label: "Abaya" },
          { id: "robes", label: "Robes" },
          { id: "ensembles", label: "Ensembles" },
          { id: "hauts", label: "Hauts" },
          { id: "pantalons", label: "Pantalons" },
        ].map((item) => (
          <label key={item.id} className="radio-line">
            <input
              type="radio"
              checked={category === item.id}
              onChange={() => handleCategory(item.id)}
            />
            {item.label}
          </label>
        ))}
      </div>

      {/* PRICE FILTER */}
      <div className="filter-section">
        <h4 className="filter-label">Prix</h4>

        <label className="radio-line">
          <input
            type="radio"
            checked={price === "all"}
            onChange={() => handlePrice("all")}
          />
          Tous
        </label>

        <label className="radio-line">
          <input
            type="radio"
            checked={price === "lt6000"}
            onChange={() => handlePrice("lt6000")}
          />
          Moins de 6000 DA
        </label>

        <label className="radio-line">
          <input
            type="radio"
            checked={price === "6000-8000"}
            onChange={() => handlePrice("6000-8000")}
          />
          6000 - 8000 DA
        </label>

        <label className="radio-line">
          <input
            type="radio"
            checked={price === "gt8000"}
            onChange={() => handlePrice("gt8000")}
          />
          Plus de 8000 DA
        </label>
      </div>

      {/* SORT */}
      <div className="filter-section">
        <h4 className="filter-label">Trier par</h4>

        <select
          className="sort-select"
          value={sort}
          onChange={(e) => handleSort(e.target.value)}
        >
          <option value="new">Nouveautés</option>
          <option value="asc">Prix croissant</option>
          <option value="desc">Prix décroissant</option>
          <option value="az">Nom A-Z</option>
        </select>
      </div>
    </div>
  );
}
